@if($rows->isNotEmpty())<div @class(['analytics-table-wrap', 'is-compact' => $compact ?? false])><table><thead><tr><th>Event</th><th>Tags</th><th>Date</th><th>Check-ins</th><th>Required</th><th>Present</th><th>Absent</th><th>Rate</th><th></th></tr></thead><tbody>@foreach($rows as $row)<tr><td><strong>{{ $row->title }}</strong><small>{{ ucfirst($row->event_type) }}</small></td><td><div class="record-tag-cell">@forelse($row->tags as $tag)<span class="group-tag-badge">{{ $tag->name }}</span>@empty<span class="group-tag-badge is-empty">No tags</span>@endforelse</div></td><td>{{ $row->event_date->format($churchSettings->date_format) }}</td><td>{{ $row->checkins_count }}</td><td>{{ $row->attendance_required ? $row->required_count : 'Optional' }}</td><td>{{ $row->attendance_required ? $row->present_count : '—' }}</td><td>{{ $row->attendance_required ? $row->absent_count : '—' }}</td><td>@if($row->attendance_required && $row->attendance_finalized_at && $row->required_count)<span class="analytics-rate">{{ round($row->present_count / $row->required_count * 100) }}%</span>@else<span class="event-muted">{{ $row->attendance_required ? 'Pending' : 'Optional' }}</span>@endif</td><td><a href="{{ route('events.view', $row) }}" wire:navigate aria-label="View {{ $row->title }}"><x-heroicon-o-chevron-right /></a></td></tr>@endforeach</tbody></table></div>@else<div class="event-empty-state event-empty-compact"><h3>No events in this month</h3><p>Choose another month or create an event.</p></div>@endif
